pub(super) fn texture_format(format: usize) -> Option<(wgpu::TextureFormat, usize)> {
    match format {
        0 => Some((wgpu::TextureFormat::Rgba8Unorm, 4)),
        1 => Some((wgpu::TextureFormat::Rgba16Float, 8)),
        2 => Some((wgpu::TextureFormat::Rgba32Float, 16)),
        3 => Some((wgpu::TextureFormat::R32Float, 4)),
        4 => Some((wgpu::TextureFormat::Rg32Float, 8)),
        _ => None,
    }
}
pub fn quantize_displacement_range(minimum: f32, maximum: f32) -> u32 {
    let lower = ((minimum * 255.0f32).floor() as i32).clamp(0, 255);
    let upper = if (maximum - minimum).abs() < 0.000001f32 { lower } else {
        ((maximum * 255.0f32).ceil() as i32).clamp(0, 255)
    };
    ((lower << 8) | upper) as u32
}
